let mockSiteSettings = {
  site_name: 'APMA - Asosiasi Profesi Marketing Asuransi',
  site_tagline: 'Membangun Profesionalisme Pemasar Asuransi Umum Indonesia',
  logo_url: '', // Kosong = pakai default logo/SVG
  hero_title: 'Membangun Profesionalisme Pemasar Asuransi Umum Indonesia',
  hero_subtitle: 'Wadah kolaborasi terdepan bagi para praktisi dan profesional pemasaran asuransi untuk meningkatkan standar industri, etika profesi, dan kompetensi global.',
  hero_image: 'https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?q=80&w=600&auto=format&fit=crop'
};

// Inisialisasi tabel site_settings jika belum ada
async function initSettingsTable() {
  try {
    await db.execute(`
      CREATE TABLE IF NOT EXISTS site_settings (
        setting_id INT AUTO_INCREMENT PRIMARY KEY,
        setting_key VARCHAR(100) NOT NULL UNIQUE,
        setting_value TEXT NULL,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
      )
    `);
  } catch (err) {
    // Database fallback
  }
}
initSettingsTable();

// --- Rute GET /api/settings ---
app.get('/api/settings', async (req, res) => {
  try {
    let settings = { ...mockSiteSettings };
    try {
      const [rows] = await db.execute('SELECT setting_key, setting_value FROM site_settings');
      if (rows && rows.length > 0) {
        rows.forEach(r => {
          settings[r.setting_key] = r.setting_value;
        });
      }
    } catch (dbErr) {
      // gunakan mock fallback
    }
    res.status(200).json({ status: 'success', data: settings });
  } catch (error) {
    console.error('Error fetching settings:', error);
    res.status(500).json({ status: 'error', message: 'Gagal mengambil pengaturan situs.' });
  }
});

// --- Rute POST /api/settings (Upload Logo & Ubah Branding) ---
app.post('/api/settings', upload.fields([
  { name: 'logo', maxCount: 1 },
  { name: 'hero_image', maxCount: 1 }
]), async (req, res) => {
  try {
    const { site_name, site_tagline, hero_title, hero_subtitle, logo_url, hero_image_url } = req.body;

    if (site_name) mockSiteSettings.site_name = site_name;
    if (site_tagline) mockSiteSettings.site_tagline = site_tagline;
    if (hero_title) mockSiteSettings.hero_title = hero_title;
    if (hero_subtitle) mockSiteSettings.hero_subtitle = hero_subtitle;

    // Handle Upload File Logo
    if (req.files && req.files['logo'] && req.files['logo'].length > 0) {
      mockSiteSettings.logo_url = '/uploads/' + req.files['logo'][0].filename;
    } else if (logo_url !== undefined) {
      mockSiteSettings.logo_url = logo_url;
    }

    // Handle Upload File Hero Image
    if (req.files && req.files['hero_image'] && req.files['hero_image'].length > 0) {
      mockSiteSettings.hero_image = '/uploads/' + req.files['hero_image'][0].filename;
    } else if (hero_image_url) {
      mockSiteSettings.hero_image = hero_image_url;
    }

    // Sinkronisasi ke MySQL jika tersedia
    try {
      for (const [key, value] of Object.entries(mockSiteSettings)) {
        await db.execute(
          'INSERT INTO site_settings (setting_key, setting_value) VALUES (?, ?) ON DUPLICATE KEY UPDATE setting_value = ?',
          [key, value, value]
        );
      }
    } catch (dbErr) {
      console.warn('DB settings sync fallback:', dbErr.message);
    }

    res.status(200).json({
      status: 'success',
      message: 'Pengaturan identitas dan logo situs berhasil disimpan!',
      data: mockSiteSettings
    });
  } catch (error) {
    console.error('Error updating settings:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memperbarui pengaturan situs.' });
  }
});

