app.post('/api/news', upload.single('featured_image'), async (req, res) => {
  try {
    const { title, category, content, author_name, status, image_url } = req.body;
    if (!title || !content) {
      return res.status(400).json({ status: 'error', message: 'Judul dan konten berita wajib diisi.' });
    }

    let featured_image = image_url || 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?q=80&w=800&auto=format&fit=crop';
    if (req.file) {
      featured_image = '/uploads/' + req.file.filename;
    }

    const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-') + '-' + Date.now();
    const finalAuthor = author_name || 'Admin Master';
    const finalCategory = category || 'Berita Asosiasi';
    const finalStatus = status || 'Published';
    const nowStr = new Date().toISOString().slice(0, 19).replace('T', ' ');

    let newId = Date.now();
    try {
      const [result] = await db.execute(
        'INSERT INTO cms_news (title, slug, content, featured_image, category, author_name, status) VALUES (?, ?, ?, ?, ?, ?, ?)',
        [title, slug, content, featured_image, finalCategory, finalAuthor, finalStatus]
      );
      if (result && result.insertId) newId = result.insertId;
    } catch (dbErr) {
      console.warn('DB news insert fallback:', dbErr.message);
    }

    const newArticle = {
      news_id: newId,
      title,
      slug,
      content,
      featured_image,
      category: finalCategory,
      author_name: finalAuthor,
      status: finalStatus,
      created_at: nowStr,
      updated_at: nowStr
    };

    mockNewsList.unshift(newArticle);

    res.status(201).json({
      status: 'success',
      message: 'Artikel berita berhasil dipublikasikan!',
      data: newArticle
    });
  } catch (error) {
    console.error('Error posting news:', error);
    res.status(500).json({ status: 'error', message: 'Gagal menambahkan berita: ' + error.message });
  }
});

// --- Rute PUT /api/news/:id (Update Berita + Ganti Foto) ---
app.put('/api/news/:id', upload.single('featured_image'), async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const { title, category, content, author_name, status, image_url } = req.body;

    let existing = mockNewsList.find(n => n.news_id === id);
    let currentImage = existing ? existing.featured_image : '';

    if (req.file) {
      currentImage = '/uploads/' + req.file.filename;
    } else if (image_url) {
      currentImage = image_url;
    }

    const finalTitle = title || (existing ? existing.title : 'Judul');
    const finalCategory = category || (existing ? existing.category : 'Berita Asosiasi');
    const finalContent = content || (existing ? existing.content : '');
    const finalAuthor = author_name || (existing ? existing.author_name : 'Admin Master');
    const finalStatus = status || (existing ? existing.status : 'Published');
    const nowStr = new Date().toISOString().slice(0, 19).replace('T', ' ');

    try {
      await db.execute(
        'UPDATE cms_news SET title = ?, category = ?, content = ?, author_name = ?, status = ?, featured_image = ?, updated_at = ? WHERE news_id = ?',
        [finalTitle, finalCategory, finalContent, finalAuthor, finalStatus, currentImage, nowStr, id]
      );
    } catch (dbErr) {
      console.warn('DB news update fallback:', dbErr.message);
    }

    if (existing) {
      existing.title = finalTitle;
      existing.category = finalCategory;
      existing.content = finalContent;
      existing.author_name = finalAuthor;
      existing.status = finalStatus;
      existing.featured_image = currentImage;
      existing.updated_at = nowStr;
    } else {
      mockNewsList.unshift({
        news_id: id,
        title: finalTitle,
        category: finalCategory,
        content: finalContent,
        author_name: finalAuthor,
        status: finalStatus,
        featured_image: currentImage,
        created_at: nowStr,
        updated_at: nowStr
      });
    }

    res.status(200).json({
      status: 'success',
      message: 'Artikel berita berhasil diperbarui!',
      data: { news_id: id, title: finalTitle, featured_image: currentImage }
    });
  } catch (error) {
    console.error('Error updating news:', error);
    res.status(500).json({ status: 'error', message: 'Gagal memperbarui berita: ' + error.message });
  }
});

// --- Rute DELETE /api/news/:id (Hapus Berita) ---
app.delete('/api/news/:id', async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    try {
      await db.execute('DELETE FROM cms_news WHERE news_id = ?', [id]);
    } catch (dbErr) {
      console.warn('DB news delete fallback:', dbErr.message);
    }

    mockNewsList = mockNewsList.filter(n => n.news_id !== id);

    res.status(200).json({
      status: 'success',
      message: 'Artikel berita berhasil dihapus.'
    });
  } catch (error) {
    console.error('Error deleting news:', error);
    res.status(500).json({ status: 'error', message: 'Gagal menghapus berita: ' + error.message });
  }
});

