        /* ================= BERITA & DOKUMEN (API GRID) ================= */
        .api-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(350px, 1fr)); gap: 2.5rem; }
        .api-card { background: var(--white); border-radius: 16px; overflow: hidden; box-shadow: var(--shadow-premium); display: flex; flex-direction: column; border: 1px solid var(--border-color); transition: all 0.3s ease; }
        .api-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); border-color: var(--primary); }
        .news-card-img { width: 100%; height: 210px; object-fit: cover; transition: transform 0.4s ease; }
        .news-img-container { width: 100%; height: 210px; overflow: hidden; background: #e2e8f0; position: relative; }
        .api-card:hover .news-card-img { transform: scale(1.05); }
        .news-card-body { padding: 1.75rem; display: flex; flex-direction: column; flex-grow: 1; }
        .news-meta { display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.85rem; font-size: 0.85rem; color: var(--text-muted); }
        .api-card h4 { font-size: 1.25rem; color: var(--secondary); margin-bottom: 0.75rem; font-weight: 700; line-height: 1.4; }
        .api-badge { display: inline-block; padding: 0.3rem 0.85rem; background: #fee2e2; color: var(--primary); border-radius: 20px; font-size: 0.8rem; font-weight: 700; }
        .api-card p { color: var(--text-muted); font-size: 0.95rem; margin-bottom: 1.5rem; flex-grow: 1; line-height: 1.6; }
        .api-link { color: var(--primary); font-weight: 700; text-decoration: none; font-size: 0.95rem; display: inline-flex; align-items: center; gap: 0.4rem; cursor: pointer; transition: color 0.2s; background: none; border: none; padding: 0; }
        .api-link:hover { color: var(--primary-hover); text-decoration: underline; }

        .loading-state { text-align: center; padding: 3rem; color: var(--text-muted); font-weight: 500; grid-column: 1 / -1; font-size: 1.1rem; }

        /* Article Reader Modal */
        .modal-overlay {
            display: none;
            position: fixed;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(15, 23, 42, 0.75);
            z-index: 2000;
            justify-content: center;
            align-items: center;
            backdrop-filter: blur(4px);
            padding: 1.5rem;
        }
        .modal-overlay.active { display: flex; }
        .reader-modal-card {
            background: var(--white);
            border-radius: 20px;
            width: 100%;
            max-width: 780px;
            max-height: 90vh;
            overflow-y: auto;
            position: relative;
            box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25);
        }
        .reader-modal-img {
            width: 100%;
            height: 320px;
            object-fit: cover;
            border-radius: 20px 20px 0 0;
        }
        .reader-modal-content {
            padding: 2.5rem;
        }
        .reader-modal-close {
            position: absolute;
            top: 1.25rem;
            right: 1.25rem;
            background: rgba(15, 23, 42, 0.6);
            color: white;
            border: none;
            width: 36px;
            height: 36px;
            border-radius: 50%;
            font-size: 1.2rem;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s;
            z-index: 10;
        }
        .reader-modal-close:hover { background: var(--primary); transform: scale(1.05); }

        /* ================= KONTAK & FOOTER ================= */
        #kontak { background-color: var(--white); border-top: 1px solid var(--border-color); }
        .contact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5rem; align-items: flex-start; }
        .contact-form .form-control { width: 100%; padding: 1rem 1.25rem; border: 1px solid var(--border-color); border-radius: 8px; font-size: 1rem; transition: all 0.3s ease; margin-bottom: 1.5rem; background-color: var(--bg-color); }
        .contact-form .form-control:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 3px rgba(153, 27, 27, 0.1); background-color: var(--white); }
        .contact-form textarea { resize: vertical; min-height: 150px; }
        .btn-submit { width: 100%; background-color: var(--primary); color: var(--white); padding: 1.1rem; border-radius: 8px; border: none; font-weight: 700; font-size: 1.1rem; cursor: pointer; transition: all 0.3s; }
        .btn-submit:hover { background-color: var(--primary-hover); box-shadow: 0 4px 12px rgba(153, 27, 27, 0.2); }

        .contact-info h3 { font-size: 1.75rem; color: var(--secondary); margin-bottom: 1.5rem; font-weight: 800; }
        .contact-info p { color: var(--text-muted); margin-bottom: 1.5rem; display: flex; align-items: flex-start; gap: 1rem; font-size: 1.05rem; }

        footer { background-color: var(--secondary); color: #94a3b8; text-align: center; padding: 2.5rem 1.5rem; font-size: 1rem; }

        @media (max-width: 900px) {
            .hero h1 { font-size: 2.5rem; }
            .about-grid, .contact-grid { grid-template-columns: 1fr; gap: 3rem; }
            .nav-links { display: none; }
            .reader-modal-img { height: 220px; }
            .reader-modal-content { padding: 1.5rem; }
        }
    </style>
